package main

import (
	"bufio"
	"fmt"
	"os/exec"
	"strconv"
	"strings"
)

// MeasureLatency pings the specified host a given number of times and returns
// the average latency in milliseconds. It uses the os/exec package to execute
// the system's ping command.
func MeasureLatency(host string, count int) (float64, error) {
	// Execute the ping command with appropriate flags for cross-platform compatibility.
	// On Linux/macOS, -c sets the count; on Windows, -n is used.
	// We try -c first (Linux/macOS), and if it fails, we fall back to -n (Windows).
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	output, err := cmd.Output()
	if err != nil {
		// Fallback for Windows: use -n flag
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
		output, err = cmd.Output()
		if err != nil {
			return 0, fmt.Errorf("ping command failed: %w", err)
		}
	}

	// Parse the output to extract the average latency.
	avgLatency, err := parseAverageLatency(string(output))
	if err != nil {
		return 0, fmt.Errorf("failed to parse ping output: %w", err)
	}

	return avgLatency, nil
}

// parseAverageLatency extracts the average round-trip time from ping output.
// It handles both Linux/macOS and Windows output formats.
func parseAverageLatency(output string) (float64, error) {
	scanner := bufio.NewScanner(strings.NewReader(output))
	for scanner.Scan() {
		line := scanner.Text()
		// Linux/macOS format: "rtt min/avg/max/mdev = 10.123/20.456/30.789/1.234 ms"
		if strings.Contains(line, "rtt min/avg/max/mdev") {
			parts := strings.Split(line, "=")
			if len(parts) < 2 {
				continue
			}
			stats := strings.TrimSpace(parts[1])
			values := strings.Split(stats, "/")
			if len(values) < 2 {
				continue
			}
			avgStr := strings.TrimSpace(values[1])
			avg, err := strconv.ParseFloat(avgStr, 64)
			if err != nil {
				return 0, fmt.Errorf("invalid average value: %s", avgStr)
			}
			return avg, nil
		}
		// Windows format: "Average = 20ms" or "Average = 20 ms"
		if strings.Contains(line, "Average") {
			parts := strings.Split(line, "=")
			if len(parts) < 2 {
