// parseAverageLatency extracts the average latency from a ping summary line.
// It expects a line in the format: ... = min/avg/max/mdev ms
func parseAverageLatency(line string) (float64, error) {
	// Find the position of "="
	eqIdx := strings.Index(line, "=")
	if eqIdx == -1 {
		return 0, fmt.Errorf("no '=' found in line: %s", line)
	}

	// Take the part after "="
