package main

import (
	"bufio"
	"fmt"
	"os/exec"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a given number of times and returns the average latency in milliseconds.
// It uses the system's ping command via os/exec.
func MeasureLatency(host string, count int) (float64, error) {
	// Prepare the ping command. The flags are chosen for cross-platform compatibility:
	// -c specifies count on Linux/macOS, -n on Windows. We'll try -c first.
	// We also use -q to get quiet output (summary only) where supported.
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), "-q", host)

	// Execute the command and capture stdout.
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return 0, fmt.Errorf("failed to create stdout pipe: %w", err)
	}

	if err := cmd.Start(); err != nil {
		return 0, fmt.Errorf("failed to start ping command: %w", err)
	}

	// Read the output line by line.
	scanner := bufio.NewScanner(stdout)
	var lastLine string
	for scanner.Scan() {
		lastLine = scanner.Text()
	}

	if err := scanner.Err(); err != nil {
		return 0, fmt.Errorf("error reading ping output: %w", err)
	}

	// Wait for the command to finish.
	if err := cmd.Wait(); err != nil {
		return 0, fmt.Errorf("ping command failed: %w", err)
	}

	// Parse the last line to extract the average latency.
	// Expected format (Linux): "rtt min/avg/max/mdev = 10.123/20.456/30.789/5.678 ms"
	// Expected format (macOS): "round-trip min/avg/max/stddev = 10.123/20.456/30.789/5.678 ms"
	// We'll look for the pattern "= X/Y/Z/W ms" and extract Y.
	avgLatency, err := parseAverageLatency(lastLine)
	if err != nil {
		return 0, fmt.Errorf("failed to parse average latency from output: %w", err)
	}

	return avgLatency, nil
}

// parseAverageLatency extracts the average latency from a ping summary line.
// It expects a line containing "= value1/value2/value3/value4 ms" and returns value2.
func parseAverageLatency(line string) (float64, error) {
	// Find the position of '=' and split.
	eqIdx := strings.Index(line, "=")
	if eqIdx == -1 {
		return 0, fmt.Errorf("no '=' found in line: %s", line)
	}

	// Extract the part after '='.
	afterEq := strings.TrimSpace(line[eqIdx+1:])

	// Split by '/' to get the values.
	parts := strings.Split(afterEq, "/")
	if len(parts) < 2 {
		return 0, fmt.Errorf("unexpected format, expected at least 2 '/' separated values: %s", afterEq)
	}

	// The average is the second value (index 1).
	avgStr := strings.TrimSpace(parts[1])

	// Remove any trailing " ms" or similar.
	avgStr = strings.TrimSuffix(avgStr, " ms")
	avgStr = strings.TrimSuffix(avgStr, "ms")
	avgStr = strings.TrimSpace(avgStr)

	avg, err := strconv.ParseFloat(avgStr, 64)
	if err != nil {
		return 0, fmt.Errorf("failed to parse average latency '%s': %w", avgStr, err)
	}

	return avg, nil
}

func main() {
	// Example usage: ping google.com 4 times and print average latency.
	host := "google.com"
	count := 4

	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency to %s: %v\n", host, err)
		return
	}

	fmt.Printf("Average latency to %s over %d pings: %.2f ms\n", host, count, avg)
}

