// MeasureLatency pings a specified host a given number of times and returns
// the average latency in milliseconds. It uses the system's ping command
// via os/exec and parses the output to extract the average round-trip time.
func MeasureLatency(host string, count int) (float64, error) {
	// Validate count parameter
	if count <= 0 {
		return 0, fmt.Errorf("count must be a positive integer, got %d", count)
	}

	// Determine the ping command arguments based on the operating system
	// (cross-platform consideration)
	var args []string
	if isWindows() {
		// Windows: ping -n <count> <host>
		args = []string{"-n", strconv.Itoa(count), host}
	} else {
		// Unix-like (Linux, macOS, etc.): ping -c <count> <host>
		args = []string{"-c", strconv.Itoa(count), host}
	}

	// Execute the ping command
	cmd := exec.Command("ping", args...)
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return 0, fmt.Errorf("failed to create stdout pipe: %w", err)
	}

	if err := cmd.Start(); err != nil {
		return 0, fmt.Errorf("failed to start ping command: %w", err)
	}

	// Read the output line by line
	scanner := bufio.NewScanner(stdout)
	var lastLine string
	for scanner.Scan() {
		lastLine = scanner.Text()
	}

	if err := scanner.Err(); err != nil {
		return 0, fmt.Errorf("error reading ping output: %w", err)
	}

	// Wait for the command to finish
	if err := cmd.Wait(); err != nil {
		return 0, fmt.Errorf("ping command failed: %w", err)
	}

	// Parse the average latency from the last line of output
	avgLatency, err := parseAverageLatency(lastLine)
	if err != nil {
		return 0, fmt.Errorf("failed to parse average latency from output: %w", err)
	}

	return avgLatency, nil
}

// isWindows checks if the current operating system is Windows.
func isWindows() bool {
	return len(os.Getenv("windir")) > 0
}

// parseAverageLatency extracts the average round-trip time from a ping output line.
// It supports both Windows and Unix-like ping output formats.
func parseAverageLatency(line string) (float64, error) {
	// Trim and normalize the line
	line = strings.TrimSpace(line)
	if line == "" {
		return 0, fmt.Errorf("empty output line")
	}

	// Attempt to find average latency in common formats:
	// Unix-like: "rtt min/avg/max/mdev = 10.123/20.456/30.789/5.678 ms"
	// Windows: "Average = 20ms" or "Average = 20 ms"

	// Try Unix-like format first
	if strings.Contains(line, "rtt") && strings.Contains(line, "=") {
		parts := strings.Split(line, "=")
		if len(parts) >= 2 {
			valuesPart := strings.TrimSpace(parts[1])
			// valuesPart looks like "10.123/20.456/30.789/5.678 ms"
			slashParts := strings.Split(valuesPart, "/")
			if len(slashParts) >= 2 {
				avgStr := strings.TrimSpace(slashParts[1])
				// Remove any trailing "ms" or whitespace
				avgStr = strings.TrimSuffix(avgStr, "ms")
				avgStr = strings.TrimSpace(avgStr)
				if avg, err := strconv.ParseFloat(avgStr, 64); err == nil {
					return avg, nil
				}
			}
		}
	}

	// Try Windows format: "Average = 20ms" or "Average = 20 ms"
	if strings.Contains(line, "Average") && strings.Contains(line, "=") {
		parts := strings.Split(line, "=")
		if len(parts) >= 2 {
			valueStr := strings.TrimSpace(parts[1])
			// Remove "ms" suffix if present
			valueStr = strings.TrimSuffix(valueStr, "ms")
			valueStr = strings.TrimSpace(valueStr)
			if avg, err := strconv.ParseFloat(valueStr, 64); err == nil {
				return avg, nil
			}
		}
	}

	// Try a more generic approach: look for a number followed by "ms" anywhere in the line
	// This is a fallback for other ping implementations
	fields := strings.Fields(line)
	for i, field := range fields {
		if field == "ms" && i > 0 {
			// Try to parse the previous field as a number
			prevField := strings.TrimSuffix(fields[i-1], "ms")
			prevField = strings.TrimSpace(prevField)
			if avg, err := strconv.ParseFloat(prevField, 64); err == nil {
				return avg, nil
			}
		}
		// Also check for fields like "20ms" (no space)
		if strings.HasSuffix(field, "ms") && len(field) > 2 {
			numStr := strings.TrimSuffix(field, "ms")
			if avg, err := strconv.ParseFloat(numStr, 64); err == nil {
				return avg, nil
			}
		}
	}

	return 0, fmt.Errorf("unable to parse average latency from line: %s", line)
}

func main() {
	// Example usage of MeasureLatency
	host := "8.8.8.8" // Default host (Google DNS)
	count := 4        // Default number of pings

	// Allow command-line arguments to override defaults
	if len(os.Args) > 1 {
		host = os.Args[1]
	}
	if len(os.Args) > 2 {
		if c, err := strconv.Atoi(os.Args[2]); err == nil && c > 0 {
			count = c
		} else {
			fmt.Fprintf(os.Stderr, "Invalid count argument, using default: %d\n", count)
		}
	}

	fmt.Printf("Measuring latency to %s with %d pings...\n", host, count)
	avgLatency, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("Average latency: %.2f ms\n", avgLatency)
}

