func MeasureLatency(host string, count int) (float64, error) {
	// Build the ping command
	// Using -c for count (Linux/macOS) and -W for timeout (Linux) or -t for timeout (macOS)
	// We'll use common flags: -c count, -W timeout (Linux) or -t timeout (macOS)
