					receivedCount++
				}
			}
		}

		// Also try to parse summary line for average
		if strings.Contains(line, "min/avg/max") || strings.Contains(line, "min/avg/max/mdev") {
			parts := strings.Split(line, "=")
			if len(parts) >= 2 {
				statsPart := strings.TrimSpace(parts[1])
				// statsPart looks like "11.234/12.345/13.456/0.789 ms" or "11.234/12.345/13.456 ms"
				statValues := strings.Split(statsPart, "/")
				if len(statValues) >= 2 {
