func MeasureLatency(host string, count int) (float64, error) {
	// Build the ping command with appropriate flags for cross-platform compatibility
	// -c for count (Linux/macOS), -n for count (Windows)
	// We'll try -c first (most common on Linux/macOS), and fallback to -n if needed
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)

	// Execute the command and capture output
	output, err := cmd.Output()
	if err != nil {
		// If -c flag fails (e.g., on Windows), try with -n flag
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
		output, err = cmd.Output()
		if err != nil {
			return 0, fmt.Errorf("failed to execute ping command: %v", err)
		}
	}

	// Parse the output to extract average latency
	avgLatency, err := parseAverageLatency(string(output))
	if err != nil {
		return 0, fmt.Errorf("failed to parse ping output: %v", err)
	}

	return avgLatency, nil
}

// parseAverageLatency extracts the average latency from ping command output.
// It supports both Linux/macOS and Windows ping output formats.
func parseAverageLatency(output string) (float64, error) {
	scanner := bufio.NewScanner(strings.NewReader(output))

	// Common patterns for average latency in ping output:
	// Linux: rtt min/avg/max/mdev = 10.123/20.456/30.789/5.678 ms
	// macOS: round-trip min/avg/max/stddev = 10.123/20.456/30.789/5.678 ms
	// Windows: Average = 20ms or Average = 20.456ms
	for scanner.Scan() {
		line := scanner.Text()

		// Try to match Linux/macOS format first
		if strings.Contains(line, "avg") || strings.Contains(line, "average") {
			// Extract the value between "/" characters
			parts := strings.Split(line, "/")
			for i, part := range parts {
				if strings.Contains(part, "avg") || strings.Contains(part, "average") {
					// The average value is typically the second value after "avg" or "average"
					// Format: ... min/avg/max ... or ... min/average/max ...
					if i+1 < len(parts) {
						avgStr := strings.TrimSpace(parts[i+1])
						// Remove any non-numeric characters (like "ms" or spaces)
						avgStr = strings.TrimRight(avgStr, "ms ")
						avg, err := strconv.ParseFloat(avgStr, 64)
						if err == nil {
							return avg, nil
						}
					}
				}
			}
		}

		// Try to match Windows format
		if strings.Contains(line, "Average =") || strings.Contains(line, "average =") {
			// Extract the value after "="
			parts := strings.Split(line, "=")
			if len(parts) >= 2 {
				avgStr := strings.TrimSpace(parts[1])
				// Remove "ms" and any other non-numeric characters
				avgStr = strings.TrimRight(avgStr, "ms ")
				avg, err := strconv.ParseFloat(avgStr, 64)
				if err == nil {
					return avg, nil
				}
			}
		}
	}

	return 0, fmt.Errorf("could not find average latency in ping output")
}

// main is an example usage of the MeasureLatency function.
