package main

import (
	"bufio"
	"fmt"
	"os/exec"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a given number of times and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	// Execute the ping command
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return 0, fmt.Errorf("failed to create stdout pipe: %w", err)
	}

	if err := cmd.Start(); err != nil {
		return 0, fmt.Errorf("failed to start ping command: %w", err)
	}

	// Read the output line by line
	scanner := bufio.NewScanner(stdout)
	var totalLatency float64
	var receivedCount int

	for scanner.Scan() {
		line := scanner.Text()
		// Look for lines containing "time=" which indicate a ping response
		if strings.Contains(line, "time=") {
			// Extract the time value (e.g., "time=10.5 ms" or "time=10.5ms")
			parts := strings.Split(line, "time=")
			if len(parts) < 2 {
				continue
			}
			timeStr := parts[1]
			// Remove any trailing " ms" or "ms"
			timeStr = strings.TrimSuffix(timeStr, " ms")
			timeStr = strings.TrimSuffix(timeStr, "ms")
			timeStr = strings.TrimSpace(timeStr)

			// Parse the latency value
			latency, err := strconv.ParseFloat(timeStr, 64)
			if err != nil {
				continue
			}
			totalLatency += latency
			receivedCount++
		}
	}

	if err := scanner.Err(); err != nil {
		return 0, fmt.Errorf("error reading ping output: %w", err)
	}

	if err := cmd.Wait(); err != nil {
		return 0, fmt.Errorf("ping command failed: %w", err)
	}

	if receivedCount == 0 {
		return 0, fmt.Errorf("no ping responses received from %s", host)
	}

	// Calculate average latency
	avgLatency := totalLatency / float64(receivedCount)
	return avgLatency, nil
}

func main() {
	// Example usage
	host := "8.8.8.8"
	count := 4

	avgLatency, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}

	fmt.Printf("Average latency to %s over %d pings: %.2f ms\n", host, count, avgLatency)
}

