package main

import (
	"bufio"
	"fmt"
	"os/exec"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a given number of times and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	// Execute the ping command with the specified host and count.
	// The "-c" flag sets the number of ping attempts (works on Linux/macOS).
	// For Windows compatibility, we could use "-n" instead, but here we assume Unix-like systems.
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	output, err := cmd.Output()
	if err != nil {
		return 0, fmt.Errorf("failed to execute ping command: %w", err)
	}

	// Parse the output to extract the average latency.
	// Typical output line: "rtt min/avg/max/mdev = 10.123/20.456/30.789/5.678 ms"
	scanner := bufio.NewScanner(strings.NewReader(string(output)))
	var avgLatency float64
	found := false
	for scanner.Scan() {
		line := scanner.Text()
		if strings.Contains(line, "rtt") && strings.Contains(line, "avg") {
			// Extract the part after "="
			parts := strings.Split(line, "=")
			if len(parts) != 2 {
				continue
			}
			stats := strings.TrimSpace(parts[1])
			// stats format: "min/avg/max/mdev ms"
			fields := strings.Split(stats, "/")
			if len(fields) < 2 {
				continue
			}
			// The second field is the average
			avgStr := strings.TrimSpace(fields[1])
			avgLatency, err = strconv.ParseFloat(avgStr, 64)
			if err != nil {
				return 0, fmt.Errorf("failed to parse average latency: %w", err)
			}
			found = true
			break
		}
	}
	if err := scanner.Err(); err != nil {
		return 0, fmt.Errorf("error reading ping output: %w", err)
	}
	if !found {
		return 0, fmt.Errorf("unable to find average latency in ping output")
	}

	return avgLatency, nil
}

func main() {
	// Example usage
	host := "google.com"
	count := 4
	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}
	fmt.Printf("Average latency to %s over %d pings: %.2f ms\n", host, count, avg)
}

