package main

import (
	"bufio"
	"fmt"
	"os/exec"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a given number of times and returns
// the average latency in milliseconds. It uses the system's ping command.
func MeasureLatency(host string, count int) (float64, error) {
	// Prepare the ping command with appropriate flags for cross-platform compatibility.
	// On Linux/macOS, use -c for count and -q for quiet output.
	// On Windows, use -n for count.
	// We'll try Linux/macOS first, then fallback to Windows if needed.
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), "-q", host)
	output, err := cmd.Output()
	if err != nil {
		// If the first attempt fails, try Windows-style ping
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
		output, err = cmd.Output()
		if err != nil {
			return 0, fmt.Errorf("ping command failed: %w", err)
		}
	}

	// Parse the output to extract average latency
	avgLatency, err := parseAverageLatency(string(output))
	if err != nil {
		return 0, fmt.Errorf("failed to parse ping output: %w", err)
	}

	return avgLatency, nil
}

// parseAverageLatency extracts the average round-trip time from ping output.
// It handles both Linux/macOS and Windows output formats.
func parseAverageLatency(output string) (float64, error) {
	scanner := bufio.NewScanner(strings.NewReader(output))
	for scanner.Scan() {
		line := scanner.Text()
		// Linux/macOS format: "rtt min/avg/max/mdev = 10.123/20.456/30.789/5.012 ms"
		if strings.Contains(line, "rtt min/avg/max/mdev") {
			parts := strings.Split(line, "=")
			if len(parts) != 2 {
				continue
			}
			stats := strings.TrimSpace(parts[1])
			values := strings.Split(stats, "/")
			if len(values) >= 2 {
				avgStr := strings.TrimSpace(values[1])
				avgStr = strings.TrimSuffix(avgStr, " ms")
				avg, err := strconv.ParseFloat(avgStr, 64)
				if err == nil {
					return avg, nil
				}
			}
		}
		// Windows format: "Average = 20ms" or "Average = 20 ms"
		if strings.Contains(line, "Average") {
			parts := strings.Split(line, "=")
			if len(parts) != 2 {
				continue
			}
			avgStr := strings.TrimSpace(parts[1])
			avgStr = strings.TrimSuffix(avgStr, "ms")
			avgStr = strings.TrimSpace(avgStr)
			avg, err := strconv.ParseFloat(avgStr, 64)
			if err == nil {
				return avg, nil
			}
		}
	}
	return 0, fmt.Errorf("average latency not found in ping output")
}

func main() {
	// Example usage
	host := "google.com"
	count := 4
	latency, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}
	fmt.Printf("Average latency to %s (%d pings): %.2f ms\n", host, count, latency)
}

