func MeasureLatency(host string, count int) (float64, error) {
	// Execute the ping command with appropriate flags for cross-platform compatibility.
	// On Linux/macOS, use -c for count and -q for quiet output.
	// On Windows, use -n for count (we'll handle both cases).
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), "-q", host)
	output, err := cmd.Output()
	if err != nil {
		// If the first attempt fails, try Windows-style ping
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
		output, err = cmd.Output()
		if err != nil {
			return 0, fmt.Errorf("failed to execute ping command: %w", err)
		}
	}

	// Parse the output to extract the average latency
	avgLatency, err := parseAverageLatency(string(output))
	if err != nil {
		return 0, fmt.Errorf("failed to parse ping output: %w", err)
	}

	return avgLatency, nil
}

// parseAverageLatency extracts the average latency from ping command output.
// It handles both Linux/macOS and Windows output formats.
func parseAverageLatency(output string) (float64, error) {
	scanner := bufio.NewScanner(strings.NewReader(output))
	for scanner.Scan() {
		line := scanner.Text()
		// Linux/macOS format: "rtt min/avg/max/mdev = 10.123/20.456/30.789/1.234 ms"
		if strings.Contains(line, "min/avg/max") {
			parts := strings.Split(line, "=")
			if len(parts) < 2 {
				continue
			}
			values := strings.TrimSpace(parts[1])
			// values looks like "10.123/20.456/30.789/1.234 ms"
			valueParts := strings.Split(values, "/")
			if len(valueParts) < 2 {
				continue
			}
			avgStr := strings.TrimSpace(valueParts[1])
			// Remove any trailing "ms" or whitespace
			avgStr = strings.TrimSuffix(avgStr, "ms")
			avgStr = strings.TrimSpace(avgStr)
			avg, err := strconv.ParseFloat(avgStr, 64)
			if err != nil {
				return 0, fmt.Errorf("cannot parse average latency: %s", avgStr)
			}
			return avg, nil
		}

		// Windows format: "Average = 20ms" or "Average = 20 ms"
		if strings.Contains(line, "Average") {
			parts := strings.Split(line, "=")
			if len(parts) < 2 {
				continue
			}
			avgStr := strings.TrimSpace(parts[1])
			// Remove "ms" and any whitespace
			avgStr = strings.TrimSuffix(avgStr, "ms")
			avgStr = strings.TrimSpace(avgStr)
			avg, err := strconv.ParseFloat(avgStr, 64)
			if err != nil {
				return 0, fmt.Errorf("cannot parse average latency: %s", avgStr)
			}
			return avg, nil
		}
	}

	return 0, fmt.Errorf("average latency not found in ping output")
}

func main() {
	// Example usage
	host := "google.com"
	count := 4
	avgLatency, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}
	fmt.Printf("Average latency to %s after %d pings: %.2f ms\n", host, count, avgLatency)
}

