package main

import (
	"bufio"
	"fmt"
	"os/exec"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a given number of times and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	// Execute the ping command with the appropriate flags for cross-platform compatibility
	// -c specifies the count on Linux/macOS, -n specifies the count on Windows
	// We'll try Linux/macOS first, then fallback to Windows if needed
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	output, err := cmd.Output()
	if err != nil {
		// If the first attempt fails, try Windows-style ping
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
		output, err = cmd.Output()
		if err != nil {
			return 0, fmt.Errorf("ping failed: %v", err)
		}
	}

	// Parse the output to extract average latency
	scanner := bufio.NewScanner(strings.NewReader(string(output)))
	var totalLatency float64
	var validCount int

	for scanner.Scan() {
		line := scanner.Text()
		// Look for lines containing "time=" (Linux/macOS) or "time<" (some variants)
		// Also look for "Average = " (Windows)
		if strings.Contains(line, "time=") {
			// Extract the time value (e.g., "time=12.3 ms" or "time=123ms")
			parts := strings.Split(line, "time=")
			if len(parts) > 1 {
				timePart := strings.Fields(parts[1])[0]
				timePart = strings.TrimSuffix(timePart, "ms")
				timePart = strings.TrimSuffix(timePart, " ms")
				if latency, err := strconv.ParseFloat(timePart, 64); err == nil {
					totalLatency += latency
					validCount++
				}
			}
		} else if strings.Contains(line, "Average = ") {
			// Windows format: "Average = 12ms"
			parts := strings.Split(line, "Average = ")
			if len(parts) > 1 {
				timePart := strings.TrimSuffix(parts[1], "ms")
				timePart = strings.TrimSpace(timePart)
				if latency, err := strconv.ParseFloat(timePart, 64); err == nil {
					totalLatency += latency
					validCount++
				}
			}
		}
	}

	if validCount == 0 {
		return 0, fmt.Errorf("no valid ping responses found")
	}

	averageLatency := totalLatency / float64(validCount)
	return averageLatency, nil
}

func main() {
	// Example usage
	host := "google.com"
	count := 4

	avgLatency, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}

	fmt.Printf("Average latency to %s after %d pings: %.2f ms\n", host, count, avgLatency)
}

