// MeasureLatency pings a specified host a given number of times and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	// Execute the ping command
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return 0, fmt.Errorf("failed to create stdout pipe: %w", err)
	}

	if err := cmd.Start(); err != nil {
		return 0, fmt.Errorf("failed to start ping command: %w", err)
	}

	// Parse the output to extract average latency
	scanner := bufio.NewScanner(stdout)
	var lastLine string
	for scanner.Scan() {
		lastLine = scanner.Text()
	}

	if err := scanner.Err(); err != nil {
		return 0, fmt.Errorf("error reading ping output: %w", err)
	}

	if err := cmd.Wait(); err != nil {
		return 0, fmt.Errorf("ping command failed: %w", err)
	}

	// Parse the last line for average latency (format: "rtt min/avg/max/mdev = ...")
	// Example: "rtt min/avg/max/mdev = 10.123/15.456/20.789/2.345 ms"
	if !strings.Contains(lastLine, "rtt") {
		return 0, fmt.Errorf("unexpected ping output format: %s", lastLine)
	}

	// Extract the part after "= "
	parts := strings.Split(lastLine, "= ")
	if len(parts) < 2 {
		return 0, fmt.Errorf("unable to parse ping output: %s", lastLine)
	}

	// The second part contains the statistics: "min/avg/max/mdev = 10.123/15.456/20.789/2.345 ms"
	statsPart := parts[1]
	// Remove " ms" suffix if present
	statsPart = strings.TrimSuffix(statsPart, " ms")
	statsPart = strings.TrimSuffix(statsPart, " ms")

	// Split by "/" to get individual values
	values := strings.Split(statsPart, "/")
	if len(values) < 2 {
		return 0, fmt.Errorf("unable to parse ping statistics: %s", statsPart)
	}

	// The second value is the average (avg)
	avgStr := values[1]
	avgLatency, err := strconv.ParseFloat(avgStr, 64)
	if err != nil {
		return 0, fmt.Errorf("failed to parse average latency: %w", err)
	}

	return avgLatency, nil
}

func main() {
	// Example usage
	host := "google.com"
	count := 4

	latency, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}

	fmt.Printf("Average latency to %s after %d pings: %.2f ms\n", host, count, latency)
}

