	for scanner.Scan() {
		line := scanner.Text()
		// Try to parse Linux/macOS format first
		if strings.Contains(line, "min/avg/max") {
			parts := strings.Split(line, "=")
			if len(parts) == 2 {
				values := strings.TrimSpace(parts[1])
				// Remove " ms" or "ms" suffix
				values = strings.ReplaceAll(values, " ms", "")
				values = strings.ReplaceAll(values, "ms", "")
				avgParts := strings.Split(values, "/")
				if len(avgParts) >= 2 {
					avgStr := strings.TrimSpace(avgParts[1])
					avg, err := strconv.ParseFloat(avgStr, 64)
					if err == nil {
