// MeasureLatency pings the specified host a given number of times and returns
// the average latency in milliseconds. It uses the system's ping command.
func MeasureLatency(host string, count int) (float64, error) {
    // Execute the ping command with the specified host and count.
    // The "-c" flag sets the number of ping attempts (Unix-like systems).
    // For Windows compatibility, we use "-n" instead. We'll try both.
    cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
    output, err := cmd.Output()
    if err != nil {
        // If the first attempt fails (e.g., Windows), try with "-n" flag.
        cmd2 := exec.Command("ping", "-n", strconv.Itoa(count), host)
        output, err = cmd2.Output()
        if err != nil {
            return 0, fmt.Errorf("ping failed: %v", err)
        }
    }

    // Parse the output to extract the average latency.
    avgLatency, err := parseAverageLatency(string(output))
    if err != nil {
        return 0, fmt.Errorf("failed to parse ping output: %v", err)
    }

    return avgLatency, nil
}

// parseAverageLatency extracts the average latency from the ping command output.
// It supports both Unix and Windows output formats.
func parseAverageLatency(output string) (float64, error) {
    scanner := bufio.NewScanner(strings.NewReader(output))
    for scanner.Scan() {
        line := scanner.Text()
        // Look for lines containing "avg" (Unix) or "Average" (Windows)
        if strings.Contains(line, "avg") || strings.Contains(line, "Average") {
            // Extract the average value (format: "avg = 12.345 ms" or "Average = 12ms")
            parts := strings.Split(line, "=")
            if len(parts) < 2 {
                continue
            }
            valueStr := strings.TrimSpace(parts[1])
            // Remove "ms" suffix if present
            valueStr = strings.TrimSuffix(valueStr, "ms")
            valueStr = strings.TrimSpace(valueStr)
            // Parse the float value
            avg, err := strconv.ParseFloat(valueStr, 64)
            if err == nil {
                return avg, nil
            }
        }
    }
    return 0, fmt.Errorf("average latency not found in output")
}

func main() {
    // Example usage
    host := "8.8.8.8"
    count := 4
    avgLatency, err := MeasureLatency(host, count)
    if err != nil {
        fmt.Printf("Error: %v\n", err)
        return
    }
    fmt.Printf("Average latency to %s over %d pings: %.2f ms\n", host, count, avgLatency)
}

