package main

import (
    "bufio"
    "fmt"
    "os/exec"
    "strconv"
    "strings"
)

// MeasureLatency pings a specified host a given number of times and returns
// the average latency in milliseconds. It uses the system's ping command
// via os/exec and parses the output to extract the average round-trip time.
func MeasureLatency(host string, count int) (float64, error) {
    // Build the ping command arguments.
    // On most Unix-like systems (Linux, macOS), the -c flag specifies count.
    // The output format includes a line like: "round-trip min/avg/max/stddev = ..."
    args := []string{"-c", strconv.Itoa(count), host}
    cmd := exec.Command("ping", args...)

    // Get the stdout pipe.
    stdout, err := cmd.StdoutPipe()
    if err != nil {
        return 0, fmt.Errorf("failed to create stdout pipe: %w", err)
    }

    // Start the command.
    if err := cmd.Start(); err != nil {
        return 0, fmt.Errorf("failed to start ping command: %w", err)
    }

    // Read the output line by line.
    scanner := bufio.NewScanner(stdout)
    var lastLine string
    for scanner.Scan() {
        lastLine = scanner.Text()
    }

    // Wait for the command to finish.
    if err := cmd.Wait(); err != nil {
        return 0, fmt.Errorf("ping command failed: %w", err)
    }

    // Check for scanner errors.
    if err := scanner.Err(); err != nil {
        return 0, fmt.Errorf("error reading ping output: %w", err)
    }

    // Parse the last line to extract the average latency.
    // Expected format (Linux): "rtt min/avg/max/mdev = 10.123/20.456/30.789/5.012 ms"
    // Expected format (macOS): "round-trip min/avg/max/stddev = 10.123/20.456/30.789/5.012 ms"
    // We look for the pattern "= X.XXX/Y.YYY/..." and extract Y.YYY.
    parts := strings.Split(lastLine, " = ")
    if len(parts) != 2 {
        return 0, fmt.Errorf("unexpected ping output format: %s", lastLine)
    }

    // The second part contains the statistics: "min/avg/max/mdev = ..."
    stats := strings.Split(parts[1], "/")
    if len(stats) < 2 {
        return 0, fmt.Errorf("unexpected statistics format: %s", parts[1])
    }

    // The second field is the average.
    avgStr := stats[1]
    avg, err := strconv.ParseFloat(avgStr, 64)
    if err != nil {
        return 0, fmt.Errorf("failed to parse average latency '%s': %w", avgStr, err)
    }

    return avg, nil
}

func main() {
    // Example usage: ping google.com 5 times.
    host := "google.com"
    count := 5
    avgLatency, err := MeasureLatency(host, count)
    if err != nil {
        fmt.Printf("Error measuring latency: %v\n", err)
        return
    }
    fmt.Printf("Average latency to %s after %d pings: %.2f ms\n", host, count, avgLatency)
}

