package main

import (
	"bufio"
	"fmt"
	"os/exec"
	"strconv"
	"strings"
)

// MeasureLatency pings the specified host a given number of times and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	// Execute the ping command with the specified host and count.
	// The "-c" flag specifies the number of pings (Linux/macOS style).
	// For Windows compatibility, we could use "-n", but we'll assume a Unix-like environment.
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	output, err := cmd.Output()
	if err != nil {
		return 0, fmt.Errorf("failed to execute ping command: %w", err)
	}

	// Parse the output to extract the average latency.
	// Typical output lines look like:
	//   round-trip min/avg/max/stddev = 10.123/12.456/15.789/1.234 ms
	// We'll search for the "avg" value.
	scanner := bufio.NewScanner(strings.NewReader(string(output)))
	var avgLatency float64
	found := false

	for scanner.Scan() {
		line := scanner.Text()
		// Look for a line containing "avg" (case-insensitive) and "ms".
		if strings.Contains(line, "avg") && strings.Contains(line, "ms") {
			// Extract the part after "avg" and before "ms".
			// The format is typically: ... avg = 12.456 ...
			// We'll split by spaces and find the token containing "avg".
			parts := strings.Fields(line)
			for i, part := range parts {
				if strings.Contains(part, "avg") {
					// The next part after "=" should be the value.
					if i+1 < len(parts) {
						// Remove trailing slash if present (e.g., "avg=12.456/")
						valueStr := strings.TrimRight(parts[i+1], "/")
						avgLatency, err = strconv.ParseFloat(valueStr, 64)
						if err != nil {
							return 0, fmt.Errorf("failed to parse average latency from '%s': %w", valueStr, err)
						}
						found = true
						break
					}
				}
			}
			if found {
				break
			}
		}
	}

	if err := scanner.Err(); err != nil {
		return 0, fmt.Errorf("error reading ping output: %w", err)
	}

	if !found {
		return 0, fmt.Errorf("could not find average latency in ping output")
	}

	return avgLatency, nil
}

func main() {
	// Example usage
	host := "google.com"
	count := 4
	latency, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}
	fmt.Printf("Average latency to %s after %d pings: %.2f ms\n", host, count, latency)
}

