// MeasureLatency pings the specified host a given number of times and returns
// the average latency in milliseconds. It uses the system's ping command.
func MeasureLatency(host string, count int) (float64, error) {
	// Execute ping command with count parameter
	// Using -c for Unix-like systems (Linux/macOS) and -n for Windows
	// We'll try Unix first, then fall back to Windows if needed
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	output, err := cmd.Output()
	if err != nil {
		// Try Windows-style ping command
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
		output, err = cmd.Output()
		if err != nil {
			return 0, fmt.Errorf("ping failed: %v", err)
		}
	}

	// Parse the output to extract average latency
	scanner := bufio.NewScanner(strings.NewReader(string(output)))
	var avgLatency float64
	found := false

	for scanner.Scan() {
		line := scanner.Text()

		// Try to match Unix-style output: "rtt min/avg/max/mdev = ..."
		if strings.Contains(line, "rtt") && strings.Contains(line, "avg") {
			// Extract the avg value from format like: "rtt min/avg/max/mdev = 10.123/20.456/30.789/5.678 ms"
			parts := strings.Split(line, "=")
			if len(parts) >= 2 {
				stats := strings.TrimSpace(parts[1])
				// Remove " ms" suffix if present
				stats = strings.TrimSuffix(stats, " ms")
				stats = strings.TrimSuffix(stats, "ms")
				stats = strings.TrimSpace(stats)

				values := strings.Split(stats, "/")
				if len(values) >= 2 {
					avgStr := strings.TrimSpace(values[1])
					avg, err := strconv.ParseFloat(avgStr, 64)
					if err == nil {
						avgLatency = avg
						found = true
						break
					}
				}
			}
		}

		// Try to match Windows-style output: "Average = 20ms"
		if strings.Contains(line, "Average") && strings.Contains(line, "=") {
			parts := strings.Split(line, "=")
			if len(parts) >= 2 {
				avgStr := strings.TrimSpace(parts[1])
				// Remove "ms" suffix
				avgStr = strings.TrimSuffix(avgStr, "ms")
				avgStr = strings.TrimSpace(avgStr)
				avg, err := strconv.ParseFloat(avgStr, 64)
				if err == nil {
					avgLatency = avg
					found = true
					break
				}
			}
		}
	}

	if !found {
		return 0, fmt.Errorf("could not parse average latency from ping output")
	}

	return avgLatency, nil
}

